BEGIN TRANSACTION;
CREATE TABLE provinces (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name_kh TEXT NOT NULL);
CREATE TABLE districts (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name_kh TEXT NOT NULL, province_id INTEGER NOT NULL REFERENCES provinces(id));
CREATE TABLE communes (id INTEGER PRIMARY KEY, code TEXT NOT NULL UNIQUE, name_kh TEXT NOT NULL, district_id INTEGER NOT NULL REFERENCES districts(id));
CREATE TABLE villages (id INTEGER PRIMARY KEY, code TEXT NOT NULL, name_kh TEXT NOT NULL, commune_id INTEGER NOT NULL REFERENCES communes(id));
CREATE INDEX idx_districts_province ON districts(province_id);
CREATE INDEX idx_communes_district ON communes(district_id);
CREATE INDEX idx_villages_commune ON villages(commune_id);
CREATE INDEX idx_villages_code ON villages(code);
